"""A minimal task board with normalized status filtering."""


def _normalize_status(status):
    """Normalize a status for whitespace-insensitive, case-folded comparison."""
    return status.strip().casefold()


def select_tasks(records, status=None):
    """Return matching task copies in original order without modifying the records."""
    if status is None:
        return [record.copy() for record in records]

    normalized_status = _normalize_status(status)
    if not normalized_status:
        return []

    return [
        record.copy()
        for record in records
        if _normalize_status(record["status"]) == normalized_status
    ]

import unittest

from taskboard import select_tasks


class NewBehaviorTests(unittest.TestCase):
    def test_query_case_and_whitespace(self):
        records = [{"id": 1, "status": "pending"}, {"id": 2, "status": "done"}]
        self.assertEqual(select_tasks(records, " DONE "), [{"id": 2, "status": "done"}])

    def test_stored_case_and_whitespace(self):
        records = [{"id": 1, "status": " DONE "}, {"id": 2, "status": "pending"}]
        self.assertEqual(select_tasks(records, "done"), [{"id": 1, "status": " DONE "}])

    def test_unicode_casefold(self):
        records = [{"id": 1, "status": "Straße"}, {"id": 2, "status": "other"}]
        self.assertEqual(
            select_tasks(records, " STRASSE "), [{"id": 1, "status": "Straße"}]
        )


if __name__ == "__main__":
    unittest.main()

import unittest

from taskboard import select_tasks


class CompatibilityTests(unittest.TestCase):
    def setUp(self):
        self.records = [
            {"id": 1, "status": "pending"},
            {"id": 2, "status": "done"},
            {"id": 3, "status": "done"},
        ]

    def test_none_returns_all(self):
        self.assertEqual(select_tasks(self.records), self.records)

    def test_exact_filter_and_order(self):
        self.assertEqual([x["id"] for x in select_tasks(self.records, "done")], [2, 3])

    def test_empty_and_unknown(self):
        self.assertEqual(select_tasks(self.records, ""), [])
        self.assertEqual(select_tasks(self.records, "missing"), [])

    def test_returns_copies(self):
        result = select_tasks(self.records, "done")
        result[0]["status"] = "changed"
        self.assertEqual(self.records[1]["status"], "done")


if __name__ == "__main__":
    unittest.main()
